mapper.select:
SELECT c.id as scene, SUM(CASE WHEN a.cpu = 0 THEN 1 ELSE 0 END) AS cpu, SUM(CASE WHEN a.ram = 0 THEN 512 ELSE 0 END) AS ram, SUM(CASE WHEN a.disk = 0 THEN 10 ELSE 0 END) AS disk FROM mp_scene_scene_config_element a, mp_sceneplugincloud_scene_config_element b , mp_cscene_cscene c where c.id in
#{item}
and a.scene = c.scene_config and b.scene = c.scene_config and a.node_id = b.scene_element and b.image_type = 'container';
